{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Codeine, which shares the query's 3-methoxy and N-methyl morphinan features, has an absolute oral bioavailability of 42-71% in healthy volunteers, supporting a high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Nalmefene, a closely related morphinan opioid, has an absolute oral bioavailability of about 53%, supporting that this scaffold can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Samidorphan, another morphinan analogue, shows an absolute oral bioavailability of 69%, providing additional evidence that morphinan derivatives with appropriate substituents can have high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Noscapine, a morphinan alkaloid, has an absolute oral bioavailability of 30%, still above the 20% threshold and supportive of high F for structurally related morphinans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Naltrexone, the highest-similarity analogue, has a low absolute oral bioavailability of about 5%, but this is largely attributed to its 3-phenolic OH and N-cyclopropylmethyl substituents causing extensive first-pass metabolism; the query has 3-methoxy and N-methyl instead, so this low-F result transfers poorly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is oxycodone, a 3-methoxy, N-methyl, 6-keto, 14-hydroxy morphinan. Supportive analogues sharing the 3-methoxy/N-methyl pattern (codeine) or the morphinan scaffold with favorable substituents (nalmefene, samidorphan, noscapine) all show oral bioavailability above 20%, often 30-70%. The low bioavailability of naltrexone is explained by structural features absent in the query, namely a free 3-phenol and N-cyclopropylmethyl group. Therefore, the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct oxycodone bioavailability record is present in the supplied evidence set.",
    "Fasted-state-specific data are limited; some supportive values were obtained with food.",
    "Naltrexone low-bioavailability records conflict with the overall supportive pattern, though structural reasoning reduces their transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

